<script setup lang="ts">
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {Play,Plus,Clock3,Folder,PenLine,Trash2,Info,X,RefreshCw,CalendarDays,Check,Undo2} from 'lucide-vue-next'
import {api,key,time,datePart,clockPart,statusNames,type Plan,type Run} from '../../app/api'
import {DirectoryPicker} from '../library'
import {ModelPicker} from '../models'
import StatusBadge from '../../components/StatusBadge.vue'
import './runs.css'
import Modal from '../../components/Modal.vue'
import SelectField from '../../components/SelectField.vue'
const modelConfigID=ref(0)
const category=ref<'manual'|'automatic'>('manual')
const props=defineProps<{ready:boolean}>()
const runs=ref<Run[]>([]),plans=ref<Plan[]>([]),error=ref(''),notice=ref(''),mode=ref(''),busy=ref(false),dialogError=ref(''),targets=ref<number[]>([]),recursive=ref(true)
const edit=ref<Plan>(),name=ref(''),kind=ref('daily'),hour=ref(2),minute=ref(30),days=ref([1]),cron=ref('0 */6 * * *'),timezone=ref('Asia/Shanghai'),enabled=ref(true),preview=ref<string[]>([])
type RestoreResult={restored:number;skipped:number;failed:number;errors:string[]}
const restoreTarget=ref<Run>(),restoring=ref(false),restoreError=ref(''),restoreResult=ref<RestoreResult>()
function askRestore(r:Run){restoreTarget.value=r;restoreError.value='';restoreResult.value=undefined}
async function restoreBatch(){if(!restoreTarget.value||restoring.value)return;restoring.value=true;restoreError.value='';try{restoreResult.value=await api<RestoreResult>(`/runs/${restoreTarget.value.id}/restore`,'POST',{});await load()}catch(e){restoreError.value=(e as Error).message}finally{restoring.value=false}}
const cancelTarget=ref<Run>(),cancelling=ref(false),cancelError=ref('')
const itemAfter=ref(0),itemPages=ref<number[]>([]),itemBusy=ref(false)
const detail=ref<Run>(),items=ref<any[]>([]),deletePlan=ref<Plan>();let timer:ReturnType<typeof setTimeout>|undefined,alive=true
const expression=computed(()=>kind.value==='hourly'?`${minute.value} * * * *`:kind.value==='daily'?`${minute.value} ${hour.value} * * *`:kind.value==='weekly'?`${minute.value} ${hour.value} * * ${days.value.join(',')}`:cron.value)
const groups=computed(()=>[{id:'automatic',title:'自动计划',description:'按设定时间自动执行，持续整理新增视频。',runs:runs.value.filter(r=>r.source==='schedule'||r.plan>0)},{id:'manual',title:'手动运行',description:'选择目录立即执行一次，运行结束后不会重复触发。',runs:runs.value.filter(r=>r.source!=='schedule'&&!r.plan)}])
const active=(r:Run)=>['queued','scanning','running','cancelling'].includes(r.status)
const running=(r:Run)=>active(r)&&!!r.started&&!r.finished
const modelName=(r:Run)=>r.model_config_title||r.request_config?.model||'—'
const modelHint=(r:Run)=>[r.model_config_title,r.request_config?.model].filter(Boolean).join(' · ')||'未记录模型'
function tokens(n:number){if(n>=999_950)return `${(n/1_000_000).toFixed(2).replace(/\.?0+$/,'')}M`;if(n>=1_000)return `${(n/1_000).toFixed(1).replace(/\.?0+$/,'')}K`;return String(n)}
function tokenHint(r:Run){return r.token_estimated_records?`累计 ${r.token_count.toLocaleString()} token；${r.token_estimated_records} 条请求使用文字粗估，未计图片 token 和无法还原的重试。`:`累计 ${r.token_count.toLocaleString()} token；来自模型返回的 usage。`}
const now=ref(Date.now())
function elapsed(r:Run){
 if(!r.started)return r.status==='queued'?'等待开始':'—'
 const start=Date.parse(r.started),end=r.finished?Date.parse(r.finished):active(r)?now.value:NaN
 if(!Number.isFinite(start)||!Number.isFinite(end))return '—'
 const seconds=Math.max(0,Math.floor((end-start)/1000))
 const days=Math.floor(seconds/86400),hours=Math.floor(seconds%86400/3600),minutes=Math.floor(seconds%3600/60)
 const parts:string[]=[]
 if(days)parts.push(`${days}d`)
 if(days||hours)parts.push(`${hours}h`)
 if(days||hours||minutes)parts.push(`${minutes}m`)
 parts.push(`${seconds%60}s`)
 return parts.join('')
}
async function load(){try{const [r,p]=await Promise.all([api<Run[]>('/runs'),api<Plan[]>('/schedules')]);if(!alive)return;now.value=Date.now();runs.value=r;plans.value=p;if(detail.value){const id=detail.value.id,after=itemAfter.value;const [run,files]=await Promise.all([api<Run>(`/runs/${id}`),api<any[]>(`/runs/${id}/items?after=${after}`)]);if(detail.value?.id===id&&itemAfter.value===after){detail.value=run;items.value=files}}}catch(e){if(alive)error.value=(e as Error).message}}
async function poll(){if(document.visibilityState==='visible')await load();if(alive)timer=setTimeout(poll,3000)}
function manual(){modelConfigID.value=0;mode.value='manual';targets.value=[];recursive.value=true;dialogError.value=''}
function plan(p?:Plan){modelConfigID.value=p?.model_config_id||0;edit.value=p;name.value=p?.name||'';targets.value=p?[...p.targets]:[];recursive.value=p?.recursive??true;kind.value=p?.kind||'daily';timezone.value=p?.timezone||'Asia/Shanghai';enabled.value=p?.enabled??true;cron.value=p?.expression||'0 */6 * * *';const parts=p?.expression.split(' ');minute.value=parts?Number(parts[0])||0:30;hour.value=parts?Number(parts[1])||0:2;days.value=parts&&p?.kind==='weekly'?parts[4].split(',').map(Number):[1];preview.value=[];dialogError.value='';mode.value='plan'}
async function showPreview(){dialogError.value='';try{preview.value=await api('/schedules/preview','POST',{expression:expression.value,timezone:timezone.value})}catch(e){dialogError.value=(e as Error).message}}
async function submit(){busy.value=true;dialogError.value='';try{if(mode.value==='manual'){const r=await api('/runs','POST',{model_config_id:modelConfigID.value,targets:targets.value,recursive:recursive.value,key:key()});notice.value=`运行 #${r.id} 已加入队列`}else{await api(edit.value?`/schedules/${edit.value.id}`:'/schedules',edit.value?'PATCH':'POST',{name:name.value,model_config_id:modelConfigID.value,targets:targets.value,recursive:recursive.value,kind:kind.value,expression:expression.value,timezone:timezone.value,enabled:enabled.value,version:edit.value?.version||0});notice.value='运行计划已保存'}mode.value='';await load()}catch(e){dialogError.value=(e as Error).message}finally{busy.value=false}}
async function toggle(p:Plan){try{await api(`/schedules/${p.id}`,'PATCH',{...p,enabled:!p.enabled});await load()}catch(e){error.value=(e as Error).message}}
async function runPlan(p:Plan){try{const r=await api(`/schedules/${p.id}/run`,'POST',{key:key()});notice.value=`运行 #${r.id} 已加入队列`;await load()}catch(e){error.value=(e as Error).message}}
async function remove(){if(!deletePlan.value)return;try{await api(`/schedules/${deletePlan.value.id}`,'DELETE',{});deletePlan.value=undefined;await load()}catch(e){error.value=(e as Error).message}}
function askCancel(r:Run){cancelTarget.value=r;cancelError.value='';detail.value=undefined}
async function confirmCancel(){if(!cancelTarget.value||cancelling.value)return;cancelling.value=true;try{await api(`/runs/${cancelTarget.value.id}/cancel`,'POST',{});cancelTarget.value=undefined;notice.value='已提交取消请求';await load()}catch(e){cancelError.value=(e as Error).message}finally{cancelling.value=false}}
async function itemPage(after:number){if(!detail.value)return;const id=detail.value.id;itemAfter.value=after;itemBusy.value=true;try{const files=await api<any[]>(`/runs/${id}/items?after=${after}`);if(detail.value?.id===id&&itemAfter.value===after)items.value=files}catch(e){error.value=(e as Error).message}finally{itemBusy.value=false}}
async function inspect(r:Run){detail.value=r;items.value=[];itemAfter.value=0;itemPages.value=[];try{const run=await api<Run>(`/runs/${r.id}`);if(detail.value?.id===r.id){detail.value=run;await itemPage(0)}}catch(e){error.value=(e as Error).message}}
onMounted(poll);onUnmounted(()=>{alive=false;clearTimeout(timer)})
</script>
<template><section><div class="page-heading"><div><h1>运行计划<span class="title-dot">.</span></h1></div></div><div v-if="error" role="alert" class="notice error">{{error}}<button @click="error='';load()">重试</button></div><div v-if="notice" role="status" class="notice success">{{notice}}<button @click="notice=''">关闭</button></div><div class="log-tabs run-tabs" aria-label="运行分类"><button :class="{active:category==='manual'}" :aria-pressed="category==='manual'" @click="category='manual'"><Play :size="18"/>手动计划和运行记录</button><button :class="{active:category==='automatic'}" :aria-pressed="category==='automatic'" @click="category='automatic'"><CalendarDays :size="18"/>自动计划和运行记录</button></div><section v-for="group in groups.filter(g=>g.id===category)" :key="group.id" class="run-section" :aria-label="group.title"><div class="section-heading run-section-heading"><div><h2>{{group.title}} <span v-if="group.id==='automatic'" class="count">{{plans.length}}</span></h2><p>{{group.description}}</p></div><button v-if="group.id==='automatic'" class="primary" @click="plan()"><Plus :size="17"/>新建计划</button><button v-else class="primary" :disabled="!ready" @click="manual"><Plus :size="17"/>选择目录并运行</button></div><template v-if="group.id==='automatic'"><div v-if="!plans.length" class="panel empty plans-empty"><CalendarDays :size="31"/><h3>暂无自动计划</h3><p>支持按小时、日、周或 Cron 执行。</p></div><div v-else class="plan-grid"><article v-for="p in plans" :key="p.id" class="panel plan-card"><header><span class="plan-icon"><Clock3 :size="19"/></span><button class="switch" :class="{on:p.enabled}" role="switch" :aria-checked="p.enabled" :aria-label="`${p.enabled?'暂停':'启用'} ${p.name}`" @click="toggle(p)"><span/></button></header><h3>{{p.name}}</h3><p class="plan-expression">{{p.kind==='hourly'?'按小时':p.kind==='daily'?'按日':p.kind==='weekly'?'按周':'Cron'}} <code>{{p.expression}}</code></p><div class="plan-meta"><span><Folder :size="14"/>{{p.targets.length}} 个目录 · {{p.recursive?'含子目录':'仅当前层'}}</span><span class="plan-paths" :title="p.target_names?.join(' · ')">{{p.target_names?.join(' · ')}}</span><span>{{p.timezone}}</span></div><div class="plan-next"><span>下次运行</span><strong>{{p.enabled?time(p.next):'已暂停'}}</strong></div><p v-if="p.last" class="help">上次：{{p.last}}</p><footer><button :disabled="!ready" @click="runPlan(p)"><Play :size="14"/>立即运行</button><button class="icon-btn" :aria-label="`编辑 ${p.name}`" @click="plan(p)"><PenLine :size="15"/></button><button class="icon-btn danger-button" :aria-label="`删除 ${p.name}`" @click="deletePlan=p"><Trash2 :size="15"/></button></footer></article></div></template><div class="section-heading recent-heading"><h3>运行记录</h3><button class="text-button" @click="load"><RefreshCw :size="14"/>刷新</button></div><div class="panel table-scroll"><table><thead><tr><th>运行</th><th>模型配置</th><th>结果</th><th>状态</th><th title="已处理请求的累计 token；优先使用模型 usage，缺失时用文字粗估">token数</th><th>开始时间</th><th>结束时间</th><th title="从实际开始到结束，不含排队等待；进行中的批次显示已耗时">总耗时</th><th></th></tr></thead><tbody><tr v-for="r in group.runs" :key="r.id"><td><strong>#{{r.id}}</strong><small class="run-source">{{r.source==='schedule'?'定时触发':r.plan?'计划立即运行':'手动触发'}}</small></td><td><span class="table-model" :title="modelHint(r)">{{modelName(r)}}</span></td><td><StatusBadge :status="r.status">{{statusNames[r.status]||r.status}}</StatusBadge></td><td class="run-status"><div class="run-status-stack"><span class="run-stat" data-stat="total">总数 {{r.discovered}}</span><span class="run-stat" data-stat="done">成功数 {{r.done}}</span><span class="run-stat" data-stat="skipped">跳过数 {{r.skipped}}</span><span class="run-stat" data-stat="failed">失败数 {{r.failed}}</span></div></td><td class="subtle run-tokens" :title="r.token_records?tokenHint(r):'暂无模型请求记录'">{{r.token_records?(r.token_estimated_records?'≈':'')+tokens(r.token_count):'—'}}</td><td class="subtle date-cell"><time v-if="r.started" class="stacked-date-time" :datetime="r.started" :title="time(r.started)"><span>{{datePart(r.started)}}</span><span>{{clockPart(r.started)}}</span></time><span v-else>—</span></td><td class="subtle date-cell"><time v-if="r.finished" class="stacked-date-time" :datetime="r.finished" :title="time(r.finished)"><span>{{datePart(r.finished)}}</span><span>{{clockPart(r.finished)}}</span></time><span v-else>—</span></td><td class="subtle run-duration" title="从实际开始到结束，不含排队等待"><span class="run-duration-value"><span v-if="running(r)" class="run-live-dot" role="img" aria-label="进行中"/><span>{{elapsed(r)}}</span></span></td><td><div class="row-actions run-actions"><button class="restore-run icon-only-action" aria-label="还原批次" :disabled="active(r)||!r.done" :title="active(r)?'请先取消并等待运行结束':'还原本批次成功改名的文件'" @click="askRestore(r)"><Undo2 :size="14"/></button><button :disabled="!active(r)||r.status==='cancelling'" class="cancel-run icon-only-action" aria-label="取消" :title="r.status==='cancelling'?'取消中':'取消运行'" @click="askCancel(r)"><X :size="16"/></button><button class="detail-button icon-only-action" aria-label="详情" title="详情" @click="inspect(r)"><Info :size="16"/></button></div></td></tr></tbody></table><div v-if="!group.runs.length" class="empty compact">暂无运行记录</div></div></section></section>
<Modal v-if="mode" :title="mode==='manual'?'手动运行':edit?'编辑运行计划':'新建运行计划'" wide @close="!busy&&(mode='')"><form @submit.prevent="submit"><template v-if="mode==='plan'"><label>计划名称<input v-model="name" required maxlength="80" placeholder="例如：每天整理旅行视频"/></label><div class="form-grid"><label>执行频率<SelectField v-model="kind" @change="preview=[]" label="执行频率" :options="[{value:'hourly',label:'按小时'},{value:'daily',label:'按日'},{value:'weekly',label:'按周'},{value:'cron',label:'Cron 表达式'}]"/></label><label>时区<input v-model="timezone" required placeholder="Asia/Shanghai"/></label></div><div v-if="kind!=='cron'" class="form-grid"><label v-if="kind!=='hourly'">小时<input type="number" v-model="hour" min="0" max="23" required/></label><label>分钟<input type="number" v-model="minute" min="0" max="59" required/></label></div><div v-if="kind==='weekly'" class="weekday-picker"><label v-for="(d,i) in ['日','一','二','三','四','五','六']" :key="i"><input type="checkbox" :value="i" v-model="days"/>周{{d}}</label></div><label v-if="kind==='cron'">Cron 表达式<input v-model="cron" aria-label="Cron 表达式" required placeholder="0 */6 * * *" class="mono"/><small class="help">五段：分 时 日 月 周。日与周同时限制时，任一匹配即触发。</small></label><div class="preview-rule"><code>{{expression}}</code><button type="button" @click="showPreview">预览执行时间<ChevronRight :size="14"/></button></div><ol v-if="preview.length" class="schedule-preview"><li v-for="p in preview" :key="p">{{p}}</li></ol></template><ModelPicker v-model="modelConfigID"/><label class="field-heading">选择目标目录</label><DirectoryPicker v-model="targets"/><label class="check-label"><input type="checkbox" v-model="recursive"/>包含所选目录的子目录</label><label v-if="mode==='plan'" class="check-label"><input type="checkbox" v-model="enabled"/>保存后启用计划</label><p class="help">已命名或手动标记已处理的视频会跳过；还原后的视频可再次处理。新文件会先进行稳定性检查。</p><div v-if="dialogError" class="notice error" role="alert">{{dialogError}}</div><div class="modal-actions"><button type="button" :disabled="busy" @click="mode=''">取消</button><button class="primary" :disabled="busy||!targets.length||!modelConfigID||mode==='manual'&&!props.ready">{{busy?'正在保存…':mode==='manual'?'开始运行':'保存计划'}}</button></div></form></Modal>
<Modal v-if="restoreTarget" :title="`还原批次 #${restoreTarget.id}`" @close="!restoring&&(restoreTarget=undefined)"><p>将本批次成功改名的文件恢复为本批次处理前的名称。</p><p class="help">已还原的文件会跳过；后续又改名、内容变化或原名被占用的文件不会强制覆盖。还原成功后可重新自动命名，已启用的定时计划也可能再次处理。</p><div v-if="restoreError" class="notice error" role="alert">{{restoreError}}</div><div v-if="restoreResult" role="status" class="notice" :class="restoreResult.failed?'error':'success'">已还原 {{restoreResult.restored}} 项 · 已还原跳过 {{restoreResult.skipped}} 项 · 失败 {{restoreResult.failed}} 项<ul v-if="restoreResult.errors.length"><li v-for="message in restoreResult.errors" :key="message">{{message}}</li></ul><p v-if="restoreResult.failed>100">仅显示前 100 条失败详情。</p></div><div class="modal-actions"><button :disabled="restoring" @click="restoreTarget=undefined">{{restoreResult?'关闭':'暂不还原'}}</button><button v-if="!restoreResult||restoreResult.failed" class="primary" :disabled="restoring" @click="restoreBatch">{{restoring?'正在还原…':restoreResult?'重试失败项':'确认还原批次'}}</button></div></Modal>
<Modal v-if="cancelTarget" title="取消运行" @close="!cancelling&&(cancelTarget=undefined)"><p>确定取消运行 #{{cancelTarget.id}}？</p><p class="help">未完成的任务将停止，已完成的改名不会撤销。定时计划仍保持原设置。</p><div v-if="cancelError" class="notice error" role="alert">{{cancelError}}</div><div class="modal-actions"><button :disabled="cancelling" @click="cancelTarget=undefined">继续运行</button><button class="cancel-run" :disabled="cancelling" @click="confirmCancel"><X :size="16"/>{{cancelling?'正在取消…':'确认取消'}}</button></div></Modal>
<Modal v-if="deletePlan" title="删除运行计划" @close="deletePlan=undefined"><p>删除“{{deletePlan.name}}”后，将不再自动触发。已有运行和历史记录会保留。</p><div class="modal-actions"><button @click="deletePlan=undefined">取消</button><button class="danger-button" @click="remove"><Trash2 :size="16"/>删除计划</button></div></Modal>
<Modal v-if="detail" :title="`运行 #${detail.id}`" wide @close="detail=undefined"><div class="run-summary"><div><span>已完成</span><strong>{{detail.done}}</strong></div><div><span>已跳过</span><strong>{{detail.skipped}}</strong></div><div><span>失败</span><strong>{{detail.failed}}</strong></div></div><details v-if="detail.prompt_body" class="prompt-preview"><summary>提示词：{{detail.model_config_title}}</summary><p>{{detail.prompt_body}}</p></details><div class="run-targets"><h3>目标目录与文件</h3><ul><li v-for="(target,i) in detail.targets" :key="target">{{detail.target_names?.[i]||`条目 #${target}`}}</li></ul><p class="help">{{detail.recursive?'包含子目录':'仅所选目标的当前层'}}</p></div><p>{{statusNames[detail.status]}} · 提交时间：{{time(detail.created)}}</p><p class="help">开始时间：{{detail.started?time(detail.started):'—'}} · 结束时间：{{detail.finished?time(detail.finished):'—'}}</p><p class="help">总耗时：{{elapsed(detail)}}（不含排队等待）</p><div v-if="detail.error" class="notice error">{{detail.error}}</div><div v-for="item in items" :key="item.id" class="run-item"><div class="run-file-paths"><strong>{{item.original_path||item.current_path||`文件 #${item.entry}`}}</strong><small v-if="item.current_path&&item.current_path!==item.original_path">当前路径：{{item.current_path}}</small></div><StatusBadge :status="item.status">{{statusNames[item.status]||item.status}}</StatusBadge><p v-if="item.message">{{item.message}}</p></div><p v-if="!items.length" class="help">{{active(detail)?'正在扫描，发现视频后会显示在这里。':'当前页没有视频任务。'}}</p><div class="pagination"><span class="subtle">第 {{itemPages.length+1}} 页 · 每页最多 100 项</span><button :disabled="!itemPages.length||itemBusy" @click="itemPage(itemPages.pop()||0)">上页文件</button><button :disabled="items.length<100||itemBusy" @click="itemPages.push(itemAfter);itemPage(items[items.length-1].id)">下页文件</button></div><div class="modal-actions"><button v-if="active(detail)" class="cancel-run" @click="askCancel(detail)"><X :size="16"/>取消运行</button><button class="primary" @click="detail=undefined">关闭</button></div></Modal></template>
